    "GGHK 立直麻将规则书": "Правила риичи-маджонга GGHK",
    "香港麻将协会发布的立直麻将规则书": "Правила риичи-маджонга, опубликованные Гонконгской ассоциацией маджонга",
    "青雀是由莫莫柴编写的一款麻雀规则，旨在寻求一种在传统麻将行牌规则框架内的做大、抢和、兜牌防守三者平衡的麻雀游戏，同时试图为各类和牌提供基于美感和难度评估的赋分参照。": "Цинцюэ — правила маджонга, созданные Момочаем. Они стремятся уравновесить сбор дорогих рук, быструю победу и защиту в рамках традиционного хода игры, а также оценивать стоимость различных победных рук по их красоте и сложности.",
    "青雀一页纸": "Цинцюэ на одном листе",
    "一页纸番种速记。": "Краткая таблица фанов на одном листе.",
    "青雀第十四版一页纸，来自 mmcr.online。": "Цинцюэ, 14-я редакция на одном листе, с mmcr.online.",
    "青雀牌例第三版第一次修订，适用于第十四版，来自 mmcr.online。": "Примеры рук Цинцюэ, 3-я редакция, исправление 1; для 14-й редакции правил. С mmcr.online.",
    "青雀第十四版第一次修订，来自 mmcr.online。": "Цинцюэ, 14-я редакция, исправление 1, с mmcr.online.",
    "青雀牌例": "Примеры рук Цинцюэ",
    "记录规则中所有番种对应的详解及牌例。": "Подробные описания и примеры всех фанов этих правил.",
    "青雀规则文档": "Документация правил Цинцюэ",
    "包含青雀规则的行牌逻辑和概念解释。": "Порядок игры и объяснение понятий Цинцюэ.",
    "MIL比赛规则。": "Правила соревнований MIL.",
    "四川麻将（SBR）竞赛规则": "Правила соревнований по сычуаньскому маджонгу (SBR)",
    "四川麻将（SBR）竞赛规则（试行 2025 版）。": "Правила соревнований по сычуаньскому маджонгу (SBR), пробная редакция 2025 года.",
    "长沙麻将是湖南地区流行的麻将玩法。": "Маджонг Чанша — популярный в Хунани вариант маджонга.",
    "长沙麻将（双鸟）规则书": "Правила маджонга Чанша (две птицы)",
    "本平台长沙麻将的规则说明（0709 更新）。": "Правила маджонга Чанша на этой платформе (обновление 0709).",
    "采用 144 张牌与 16 张手牌，并以台数结算的台湾麻将规则。": "Тайваньский маджонг с набором из 144 костей, рукой из 16 костей и расчётом в таях.",
    "台湾麻将台数表": "Таблица таев тайваньского маджонга",
    "本平台台湾麻将采用的台数参考表。": "Справочная таблица таев тайваньского маджонга на этой платформе.",
    "十样锦麻将": "Маджонг Шиянцзинь",
    "尚未实装该规则，此处仅提供规则书查阅。": "Эти правила ещё не реализованы; здесь доступен только текст правил.",
    "十样锦麻将规则书": "Правила маджонга Шиянцзинь",
    "十样锦麻将规则说明。": "Описание правил маджонга Шиянцзинь.",
    "本规则为根据《绘图麻雀牌谱》《想定宁波规则》等书籍文献资料汇总而成的，试图还原1920年代左右或以前的早期麻将样貌的麻将规则。相比现代规则，古典麻雀有番种体系简单、重刻杠幺九、未和牌家计分等特点，具有独特风味。": "Эти правила составлены по книгам «Иллюстрированные записи маджонга», «Предполагаемые правила Нинбо» и другим источникам, чтобы восстановить облик раннего маджонга примерно 1920-х годов и ранее. В отличие от современных правил, классический маджонг отличается простой системой фанов, акцентом на пангах, конгах и терминальных костях, а также начислением очков непобедившим игрокам.",
    "平台现行的古典麻将版本。": "Текущая версия классического маджонга на платформе.",
    "■ 比赛列表": "■ Список турниров",
    "比赛 - salasasa.cn": "Турниры - salasasa.cn",
    "13 张直接显示听牌与进张，14 张显示切牌分析（副露按等价张数计算）。输入为空时将随机生成示例。": "Для 13 костей сразу показываются готовность и улучшающие кости, для 14 — анализ сноса (открытые сеты учитываются по эквивалентному числу костей). При пустом вводе создаётся случайный пример.",
