    "国标计算器 - salasasa.cn": "Калькулятор MCR - salasasa.cn",
    "对局开始前服务器公布承诺值 = SHA256(主种子 + 盐值)，对局结束后公布主种子与盐值。 在此本地复现随机座位与每局配牌，验证服务器未中途更换种子。计算均在浏览器内完成。": "Перед началом игры сервер публикует обязательство = SHA256(основное зерно + соль), а после игры раскрывает основное зерно и соль. Здесь можно локально воспроизвести случайную рассадку и каждую раздачу, чтобы проверить, что сервер не менял зерно в ходе игры. Все расчёты выполняются в браузере.",
