    "牌谱格式转换": "Конвертация записей",
    "浏览器本地转换，支持国标：雀渣 ↔ salasasa ↔ Botzone；日麻：salasasa ↔ MJAI。 反向重建（尤其 Botzone→salasasa、salasasa→雀渣）在隐藏信息处为近似，请核对后再用于训练。": "Локальная конвертация в браузере. MCR: Quezha ↔ salasasa ↔ Botzone; риичи: salasasa ↔ MJAI. При обратном восстановлении (особенно Botzone→salasasa и salasasa→Quezha) скрытые данные приблизительны; проверьте их перед использованием для обучения.",
