    "摸 1 万 → [\"d\", 11]；手切 3 饼 → [\"c\", 23, \"F\"]": "Взятие 1 символа → [\"d\", 11]; снос 3 точек из руки → [\"c\", 23, \"F\"]",
    "番种 y → hu_fan\t完整\t用网页 FAN[] 表把番种编号还原成中文名。": "Фан y → hu_fan\tПолностью\tВосстановление китайских названий фанов по номерам через веб-таблицу FAN[].",
