    "（北京时间 04:00 切日，每天 04:00 刷新；按段位 PT 净变更累计）": "(Граница суток и ежедневное обновление — 04:00 по Пекину; суммируется чистое изменение ранговых PT)",
    "北京时间每天 04:00 刷新最近七个完整统计日的段位 PT 变更榜。": "Рейтинг изменений ранговых PT за последние семь полных статистических суток обновляется ежедневно в 04:00 по Пекину.",
    "部分历史对局未保存 PT，当前榜单仅统计已记录的 PT 变更。": "Для части старых игр PT не сохранялись. Текущий рейтинг учитывает только записанные изменения PT.",
