    "赛事用于限时比赛；基地用于长期活动室。两者并列，审批通过后申请人成为主管理员。": "Турнир предназначен для соревнований с ограниченным сроком, клуб — для постоянной игровой комнаты. Это равноправные варианты; после одобрения заявитель становится главным администратором.",
