    "第三名扣除“段位均失 PT × 0.3 × 局制系数”，第四名扣除“段位均失 PT × 0.7 × 局制系数”。东风 0.49、半庄 0.7、全庄 1。": "За третье место списывается «средняя потеря PT ранга × 0.3 × коэффициент формата», за четвёртое — «средняя потеря PT ранга × 0.7 × коэффициент формата». Коэффициенты: Восток 0.49, ханчан 0.7, полная игра 1.",
