    "10级－3级": "10-й–3-й кю",
    "国标十六张：扩展规则与牌例": "MCR с шестнадцатью костями: расширенные правила и примеры",
    "以新编 MCR 为底本的本站十六张扩展，含逐番适用表与五面子计分补则。": "Расширение сайта до шестнадцати костей на основе новой редакции MCR, с таблицей применимости фанов и дополнениями к подсчёту пяти сетов.",
    "四人立直麻将，支持多种规则预设及役种、计分和流局设置": "Риичи-маджонг на четверых с различными наборами правил и настройками яку, подсчёта очков и ничьих",
    "香港麻将协会发布的立直麻将规则书。": "Правила риичи-маджонга, опубликованные Гонконгской ассоциацией маджонга.",
    "全国雀庄公式战手册 v1.0": "Руководство официальных игр маджонг-клубов страны v1.0",
    "雀庄公式战预设所依据的公开手册。": "Открытое руководство, на котором основан набор правил официальных клубных игр.",
    "查看公开手册": "Открыть руководство",
    "台湾麻将：使用144张牌与16张手牌，按台计分，支持公开报听、食替限制与八仙过海等规则。具体流程与台表可在馆规设置中选择。": "Тайваньский маджонг: 144 кости, рука из 16 костей, подсчёт в таях. Поддерживаются открытое объявление готовности, ограничения куикаэ, восемь бессмертных и другие правила. Порядок игры и таблица таев выбираются в настройках клубных правил.",
    "四川麻将（血战到底）": "Сычуаньский маджонг (кровавая битва до конца)",
    "长沙麻将经典双鸟规则：108张数牌，可吃上家牌，258将小胡，大胡可叠加，和牌后翻两只鸟并按座位中鸟加倍。": "Классический маджонг Чанша с двумя птицами: 108 числовых костей, чоу со сноса слева, пара из 2, 5 или 8 для малой победы, суммирование больших побед. После победы открываются две птицы, попадания по местам удваивают выплаты.",
    "本平台长沙麻将规则说明。": "Правила маджонга Чанша на этой платформе.",
    "也叫 MCR、中国麻将竞赛规则": "Также называется MCR, китайскими соревновательными правилами маджонга",
    "计分": "Подсчёт очков",
