    "地方规则与未定年线索": "Местные правила и недатированные сведения",
    "多版／平台伞称（1998原本另列）": "Общее название версий и реализаций (оригинал 1998 года отдельно)",
    "国标麻将规则资料，包含 Natsuki 编著的《新编 MCR》及各改编版本规则书。": "Материалы о правилах MCR, включая «Новую редакцию MCR» Natsuki и различные переработанные версии.",
    "国标是多版规则及平台实现的伞称。1998原本题署7月、9月初版；WMO 2006和赛事补充须另看具名版本。平台使用的新编MCR不应与1998全文等同，原目录11月出台说已按原书更正。": "MCR — общее название нескольких редакций и реализаций платформ. Оригинал 1998 года датирован июлем, первое издание — сентябрём. WMO 2006 и турнирные дополнения следует рассматривать отдельно по названным версиям. Новая редакция MCR платформы не равнозначна полному тексту 1998 года; прежнее указание ноября исправлено по оригиналу.",
