    "宝牌输入实际张数。四人日麻：食断、累计役满、复合役满开启；双倍役满、切上满贯关闭。不含本场与供托。": "Укажите фактическое число дор. Риичи на четверых: открытое танъяо, казоэ-якуман и сложение якуманов включены; двойные якуманы и округление до мангана выключены. Хонба и ставки риичи не учитываются.",
