    "青雀麻将计算器：精算番值与底分 - Salasasa": "Калькулятор Цинцюэ: точная стоимость фанов и базовые очки - Salasasa",
    "在浏览器本地计算青雀精算番值、底分与和牌拆解，未和牌时分析向听和进张。": "Локальный расчёт точной стоимости фанов, базовых очков и разложений победной руки Цинцюэ в браузере; для неполной руки — анализ шантена и улучшающих костей.",
    "青雀麻将,青雀计算器,精算番值": "маджонг Цинцюэ,калькулятор Цинцюэ,точная стоимость фанов",
    "日麻计算器：役种、番符与点数 - Salasasa": "Калькулятор риичи: яку, ханы, фу и очки - Salasasa",
    "在浏览器本地计算四人日麻役种、番符与点数，支持向听、进张与切牌分析。": "Локальный расчёт яку, ханов, фу и очков риичи на четверых в браузере. Анализ шантена, улучшающих костей и сноса.",
    "日麻计算器,立直麻将,番符计算,点数计算": "калькулятор риичи,риичи-маджонг,расчёт ханов и фу,расчёт очков",
    "青雀牌理：向听、进张与和牌得分 - Salasasa": "Анализ руки Цинцюэ: шантен, улучшающие кости и очки победы - Salasasa",
    "青雀本地牌理分析，支持七对、十三幺及一般和牌形，和牌时显示精算番值与底分。": "Локальный анализ руки Цинцюэ: семь пар, тринадцать сирот и обычная структура. При победе показываются точная стоимость фанов и базовые очки.",
    "青雀牌理,向听,进张": "анализ руки Цинцюэ,шантен,улучшающие кости",
