    "日麻本地牌理分析，支持七对子、国士无双及一般和牌形，和牌时显示役种、番符和点数。": "Локальный анализ руки риичи: чиитойцу, кокуши мусо и обычная структура. При победе показываются яку, ханы, фу и очки.",
