    "我想添加自己的麻将规则\n(点击这里)": "Хочу добавить свои правила маджонга\n(нажмите здесь)",
    "北京麻将（吃碰提）是北京地区的民间麻将规则，其特点为有字牌、无花牌、有万能牌、非门前清状态不可点和，番种体系较为简单。本文参考网络资料与线下实践梳理北京麻将的基本玩法，体现北京麻将核心特征，便于各地麻将爱好者了解北京麻将主要框架。": "Пекинский маджонг (чи-пэн-ти) — местные народные правила: с благородными костями, без цветов, с джокерами; победа со сноса допустима только на закрытой руке, система фанов проста. Текст обобщает интернет-материалы и очную практику, передавая основные особенности пекинского маджонга для знакомства игроков из других регионов с его устройством.",
