    "  项目简介": "  О проекте",
    "open_mahjong_unity是一款基于unity/python-fastapi的麻将平台项目，该项目遵循MIT许可协议、免费、开源、支持PC/安卓/ios三端互通；目标是支持所有麻将规则、并且提供给玩家自定义规则的选项。欢迎加入q群906497522参与讨论、协助和测试。": "open_mahjong_unity — бесплатная платформа маджонга с открытым кодом на unity/python-fastapi по лицензии MIT. Поддерживает совместную игру PC/Android/iOS. Цель — поддержка всех правил маджонга и возможность создания собственных. Вступайте в группу QQ 906497522 для обсуждения, помощи и тестирования.",
    "  随机种子": "  Случайное зерно",
    "在玩家 A 出牌时，若玩家 B、C 可对该出牌进行操作，则 B、C 会提前看到这张出牌；玩家 D 则会延迟一个「鸣牌保护时间」才看到出牌。若在鸣牌保护时间内 B、C 对出牌进行了操作，玩家 D 会立刻看见出牌，并在「第一追赶时间」之后再看见 B、C 其一执行的鸣牌申请或鸣牌。\n\n由于玩家 D 必定延迟一个第一追赶时间才看见 B、C 其一的鸣牌，若 B、C 在吃碰后快速出牌，这张出牌在 D 的视角中会显得「即时」。因此平台在触发鸣牌保护后进行出牌时，会保证至少再经过「第二追赶时间」才播放动画，避免在 D 的视角中出牌紧贴在吃碰之后生效。\n\n当前默认配置：\n鸣牌保护时间：1.3s\n第一追赶时间：0.7s\n第二追赶时间：0.5s": "Когда A сносит кость, B и C, способные на неё отреагировать, видят её раньше. D увидит её после «времени защиты объявления». Если B или C действует в этот период, D сразу увидит снос, а после «первой задержки синхронизации» — запрос объявления или само объявление B либо C.\n\nПоскольку D видит объявление B или C с задержкой первой задержки синхронизации, быстрый снос после чоу или панга может выглядеть для D «мгновенным». Поэтому после срабатывания защиты платформа ждёт как минимум «вторую задержку синхронизации» перед анимацией сноса, чтобы для D он не следовал вплотную за чоу или пангом.\n\nТекущие настройки по умолчанию:\nЗащита объявления: 1.3s\nПервая задержка синхронизации: 0.7s\nВторая задержка синхронизации: 0.5s",
    "战术鸣牌的设计来源于雀渣：在其他家申请鸣牌以后，可用更高优先级的操作打断他家更低优先级的操作，以模拟线下刻意「碰断吃」等战术。\n\n示例一：玩家 A 出牌 T，玩家 B 可吃、玩家 C 可碰。此时 C 选择跳过，但 B 点击了吃牌；由于仍存在可执行的更高优先级操作，系统会再次询问 C 是否要碰，以模拟国标线下允许刻意用碰打断别人吃的情形。\n\n示例二：玩家 A 出牌 T，玩家 B 可吃或和牌，玩家 C 可碰。B 选择吃，C 用碰打断了 B 的吃；此时 B 不再能用和去打断 C 的碰。这符合国标不允许玩家在鸣牌发声后更改自己要执行动作的规则。": "Тактические объявления заимствованы из Quezha: после запроса объявления другого игрока можно прервать его менее приоритетное действие более приоритетным, имитируя очную тактику, например намеренное прерывание чоу пангом.\n\nПример 1: A сносит T, B может объявить чоу, C — панг. C пропускает, но B выбирает чоу. Поскольку более приоритетное действие ещё возможно, система снова спрашивает C о панге. Так моделируется разрешённое в очном MCR намеренное прерывание чужого чоу пангом.\n\nПример 2: A сносит T, B может объявить чоу или победу, C — панг. B выбирает чоу, C прерывает его пангом. Теперь B уже не может прервать панг C победой. Это соответствует правилу MCR, запрещающему менять действие после произнесения объявления.",
    "  添加规则": "  Добавление правил",
