    "手牌牌面背景：用于在手牌牌面使用透明通道的情况下替换背景，默认尺寸 272*389。\n手牌牌背：用于在里宝牌区或者2D展示中显示牌背\n3D牌面背景：用于在3D卡牌的正面叠底在3D花纹下显示\n上传成对 zip格式：hand-back.png + hand-bg.png。": "Фон костей в руке: заменяет фон при наличии альфа-канала в изображении, стандартный размер 272*389.\nРубашка костей в руке: отображается в области ура-дор или в 2D.\nФон костей 3D: подложка под рисунком на лицевой стороне 3D-кости.\nФормат парного zip: hand-back.png + hand-bg.png.",
