    "C 为负数时是保护奖励；PT 保留两位小数。十段固定 100/100 PT，每场变动为 0。": "Отрицательное C — защитный бонус; PT сохраняются с двумя знаками после запятой. На 10-м дане всегда 100/100 PT, изменение за игру — 0.",
    "立直 · 段位升降与扣分表": "Риичи · Повышения, понижения и списания",
    "各名次扣相同的 C；东风整体乘 0.7，负数为保护奖励。特许可突破最低段位；— 为禁入场次。": "На всех местах списывается одинаковое C; для тонпусэна весь результат умножается на 0.7. Отрицательное значение — защитный бонус. Особый допуск позволяет обойти минимальный ранг; — означает недоступную комнату.",
