    "装扮": "Оформление",
    "点击改名": "Нажмите для смены имени",
    "段位与匹配说明": "О рангах и подборе",
    "为适配不同人数的游玩规则的匹配机制，平台目前提供以下两种段位设计\n1.对于每日对于超过100局的麻将规则，使用以级段制为主的段位系统\n2.对于每日对局低于100局的麻将规则，使用以elo为主的匹配系统进行对局，待人数提升后，按照elo排名设计级段制段位，并通过elo对玩家的段位进行赋分\n3.对于娱乐、开发中或不需添加段位机制的规则，不开设段位匹配场": "Для подбора соперников в правилах с разной численностью игроков платформа использует две системы рангов:\n1. Для правил с более чем 100 играми в день — преимущественно систему кю и данов.\n2. Для правил с менее чем 100 играми в день — подбор по Elo. Когда игроков станет больше, по рейтингу Elo будет создана система кю и данов с начальным присвоением рангов по Elo.\n3. Для развлекательных, разрабатываемых или не требующих рангов правил рейтинговые комнаты не создаются",
    "Elo 匹配\n\n各规则独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副）。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32；川麻 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n青雀使用独立的局均素点算法，详见青雀页面。国标、立直仅结算段位/PT；自定义对局不计分。": "Подбор Elo\n\nУ каждого набора правил отдельный рейтинг. Хунцюэ: половина игры из 8 сдач или полная из 16. Сычуаньская кровавая битва и кровавый поток с обменом тремя: половина игры (8 сдач). Подбор идёт в порядке вступления; четверо сразу начинают игру.\nНачальный R = 1500, знаменатель 2400. Для Хунцюэ K=16 за половину игры и K=32 за полную; для сычуаньского K=32. Итоговое место сравнивается с тремя соперниками, равенство считается ничьей. При среднем R стола ниже 1500 добавляется защита; личного нижнего предела нет.\n\nЦинцюэ использует отдельный алгоритм средних игровых очков за сдачу, описанный на его странице. MCR и риичи учитывают только ранги/PT; пользовательские игры очков не дают.",
    "放弃比赛": "Покинуть матч",
    "检测到您有一场正在进行的游戏，是否返回游戏?": "У вас есть текущая игра. Вернуться в неё?",
    "刷新房间列表成功": "Список комнат обновлён",
    "Elo 匹配\n\n青雀、虹雀、川麻血战、血流换三张独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副），青雀为全庄战。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32，两种局制共用虹雀积分；其他 Elo 规则 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n问号内显示算法。国标、立直仅结算段位/PT；自定义对局不计分。": "Подбор Elo\n\nЦинцюэ, Хунцюэ, сычуаньская кровавая битва и кровавый поток с обменом тремя имеют отдельные рейтинги. Хунцюэ: половина игры из 8 сдач или полная из 16; сычуаньские варианты: половина игры (8 сдач); Цинцюэ: полная игра. Подбор в порядке вступления; четверо сразу начинают игру.\nНачальный R = 1500, знаменатель 2400. Для Хунцюэ K=16 за половину игры и K=32 за полную; оба формата используют общий рейтинг Хунцюэ. Для остальных правил Elo K=32. Итоговое место сравнивается с тремя соперниками, равенство считается ничьей. При среднем R стола ниже 1500 добавляется защита; личного нижнего предела нет.\n\nАлгоритм показан под знаком вопроса. MCR и риичи учитывают только ранги/PT; пользовательские игры очков не дают.",
