    "国标麻将 / 第 01 课": "MCR / Урок 01",
    "01 / 认识一副牌": "01 / Знакомство с набором",
    "一副国标麻将，一共 144 张": "В наборе MCR всего 144 кости",
    "把牌先分成三类：数牌、字牌、花牌。\n不用急着记番种，今天先认清牌面。": "Сначала разделим кости на три категории: числовые, благородные и цветы.\nНе спешите учить фаны; сегодня познакомимся с рисунками костей.",
    "数牌 / 108 张": "Числовые / 108 костей",
    "五筒": "5 точек",
    "字牌 / 28 张": "Благородные / 28 костей",
    "白板": "Белый дракон",
    "花牌 / 8 张": "Цветы / 8 костей",
    "记住三个名字：数牌 · 字牌 · 花牌": "Запомните три названия: числовые · благородные · цветы",
    "琪露诺": "Чирно",
    "欢迎来到麻雀教室！我是琪露诺。先一起认识麻将牌吧——数牌 108 张，字牌 28 张，再加 8 张花牌。": "Добро пожаловать на урок маджонга! Я Чирно. Давайте познакомимся с костями: 108 числовых, 28 благородных и ещё 8 цветов.",
    "< 上一页": "< Предыдущая",
    "从头学习": "Учиться с начала",
    "下一页  >": "Следующая >",
    "查看规则书(跳转网页)": "Открыть правила (переход на сайт)",
    "查看XX规则规则书": "Посмотреть книгу правил XX",
    "同一门两副相同的顺子。": "Два одинаковых чоу одной масти.",
    "计番说明": "Пояснение подсчёта",
    "规则简介": "Обзор правил",
    "输入牌谱id": "Введите ID записи",
    "查看牌谱": "Посмотреть запись",
    "创建基地": "Создать клуб",
    "基地信息": "Информация о клубе",
    "基地完整名称": "Полное название клуба",
    "基地 / 社团的简单介绍": "Краткое описание клуба / сообщества",
    "备注（可选）": "Примечания (необязательно)",
    "给予管理员的说明": "Пояснения администратору",
    "姓名 / 惯用 ID": "Имя / привычный ID",
    "联系电话": "Контактный телефон",
    "本地预览 · 未提交申请": "Локальный предпросмотр · заявка не отправлена",
    "预览申请": "Предпросмотр заявки",
    "创建赛事": "Создать турнир",
    "赛事完整名称": "Полное название турнира",
    "赛事介绍与报名联系方式": "Описание турнира и контакты для регистрации",
    "基地申请预览": "Предпросмотр заявки на клуб",
    "返回修改": "Вернуться к редактированию",
    "<b>青雀 · 局均素点 Elo</b>\n初始 R = 1500；全庄与无固定时限共用积分。\nN = 实际完成局数（包含流局），Y = 累计净素点。\n局均 A = Y / N；桌均 M = 四人 R 的平均值。\n预期局均 = (自己 R - M) / 32\n普通变化 = 32N / (N + 1584) × (A - 预期局均)\n不按名次计分，不设涨跌硬上限。\n保护系数 K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((对手 R - 自己 R) / 2400))\nE' = 1 / (1 + 10^((对手 R + T - 自己 R) / 2400))\n指数限制在 -16 至 16；合计为三个对手之和。\n保护奖励 = (K / 3) × 合计(E - E')\n新 R = 原 R + 普通变化 + 保护奖励。\n普通变化按分币分配余差保持零和，保护另取两位。\n同为1500分、16局：净赢800加16，1600加32。\n未完成局不计入；零完成局不结算。": "<b>Цинцюэ · Elo по средним игровым очкам за сдачу</b>\nНачальный R = 1500; полная игра и игра без фиксированного времени используют общий рейтинг.\nN = число завершённых сдач (включая ничьи), Y = суммарный чистый результат в игровых очках.\nСреднее за сдачу A = Y / N; среднее стола M = среднее R четырёх игроков.\nОжидаемое среднее = (свой R - M) / 32\nОбычное изменение = 32N / (N + 1584) × (A - ожидаемое среднее)\nМеста не учитываются, жёсткого предела роста и падения нет.\nКоэффициент защиты K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((R соперника - свой R) / 2400))\nE' = 1 / (1 + 10^((R соперника + T - свой R) / 2400))\nПоказатель степени ограничен от -16 до 16; сумма берётся по трём соперникам.\nЗащитный бонус = (K / 3) × сумма(E - E')\nНовый R = прежний R + обычное изменение + защитный бонус.\nОстаток округления обычных изменений распределяется сотыми для сохранения нулевой суммы; защита округляется до двух знаков отдельно.\nПри одинаковых 1500 очках и 16 сдачах: чистый выигрыш 800 даёт +16, 1600 даёт +32.\nНезавершённые сдачи не учитываются; при нуле завершённых сдач расчёта нет.",
