    "风牌六对": "Шесть пар ветров",
    "包含风牌六对以上的七对和牌。": "Выигрышная рука из семи пар, содержащая не менее шести пар ветров.",
    "铳和；门风南": "Победа со сноса; ветер места — Юг",
    "和牌中有三元刻各一。": "В выигрышной руке по одному пангу каждого из трёх драконов.",
    "和牌中三元齐备，其中两种成刻，余下一种作为雀头。": "В выигрышной руке присутствуют все три дракона: два образуют панги, третий — пару.",
    "三元六对": "Шесть пар драконов",
    "包含三元对子各二的七对和牌。": "Выигрышная рука из семи пар, содержащая по две пары каждого дракона.",
    "三元对": "Пары драконов",
    "同时包含三元对子的七对和牌。": "Выигрышная рука из семи пар, содержащая пары всех трёх драконов.",
    "番牌四刻": "Четыре ценных панга",
    "和牌中有番牌（门风牌、中、發、白）刻子各一。": "В выигрышной руке по одному пангу ценных костей: ветра места, Красного, Зелёного и Белого драконов.",
    "番牌三刻": "Три ценных панга",
    "和牌中有番牌刻子至少三副。": "В выигрышной руке не менее трёх пангов ценных костей.",
