    "番牌二刻": "Два ценных панга",
    "和牌中有番牌刻子至少二副。": "В выигрышной руке не менее двух пангов ценных костей.",
    "番牌刻": "Ценный панг",
    "和牌中有番牌刻子。": "В выигрышной руке есть панг ценных костей.",
