    "仅由番牌对子组成的七对和牌。": "Выигрышная рука из семи пар, состоящая только из ценных костей.",
    "番牌六对": "Шесть ценных пар",
    "包含番牌六对以上的七对和牌。": "Выигрышная рука из семи пар, содержащая не менее шести пар ценных костей.",
    "铳和；门风北": "Победа со сноса; ветер места — Север",
    "番牌五对": "Пять ценных пар",
    "包含番牌五对以上的七对和牌。": "Выигрышная рука из семи пар, содержащая не менее пяти пар ценных костей.",
    "番牌四副": "Четыре ценные группы",
    "和牌中有番牌四副（对子或刻子）以上。": "В выигрышной руке не менее четырёх групп ценных костей (пар или пангов).",
