    "七对和牌中，有独立的两组三色三副序数相同的对子。": "В выигрышной руке из семи пар две отдельные группы по три пары трёх мастей с одинаковым номиналом.",
    "三色同对": "Одинаковые пары трёх мастей",
    "七对和牌中，有三色三副序数相同的对子。": "В выигрышной руке из семи пар три пары трёх мастей с одинаковым номиналом.",
