    "和牌中有三色三副序数依次递增1的刻子。": "В выигрышной руке три панга трёх мастей, номиналы которых последовательно возрастают на 1.",
    "三色贯通": "Ряд трёх мастей",
    "和牌中有三色三副序数依次递增3的顺子，即一色的123、另一色的456和余下一种花色的789。": "В выигрышной руке три чоу трёх мастей, номиналы которых последовательно возрастают на 3: 123 одной масти, 456 другой и 789 третьей.",
    "镜同": "Двойное отражение",
    "和牌中有两色序数牌各组成两副面子，其中对于一种花色的任一面子，在另一种花色中均有与之序数相同的面子；此处刻子是否成杠均不作区分。": "В выигрышной руке по два сета числовых костей двух мастей; каждому сету одной масти соответствует сет другой масти с такими же номиналами. Панги и конги здесь не различаются.",
    "镜同三对": "Три отражённые пары",
    "在七对和牌中，有三个同花色的序数牌对子，且另一序数牌花色中有三个序数与它们对应相同的对子。": "В выигрышной руке из семи пар три пары числовых костей одной масти и три пары другой масти с соответствующими номиналами.",
    "镜同二对": "Две отражённые пары",
    "在七对和牌中，有两个同花色的序数牌对子，且另一序数牌花色中有两个序数与它们对应相同的对子。": "В выигрышной руке из семи пар две пары числовых костей одной масти и две пары другой масти с соответствующими номиналами.",
