    "鹫巢麻将规则变体，四位玩家分为A、B两队，助手坐上家，主将坐下家，副将无击飞，最终两队只比对主将的分数判断胜负，鹫巢双打没有连庄。": "Вариант маджонга Васидзу. Четыре игрока делятся на команды A и B; помощник сидит слева от капитана. Помощники не вылетают. Победитель определяется только сравнением итоговых очков капитанов. В парном Васидзу нет повторного дилерства.",
