    "步时不能为负数": "Время на ход не может быть отрицательным",
    "无癞子奖励：可选无癞子+8分（默认）、无癞子翻倍或不额外加分。先以不含花分和奖励的牌型番判定起和，再对牌型番加黑花分进行奖励；国标支付底分8不变。花杠不享受无癞子奖励。": "Бонус за отсутствие джокеров: +8 очков (по умолчанию), удвоение или без дополнительных очков. Минимум для победы сначала проверяется по очкам за фаны без цветов и бонуса; затем бонус применяется к сумме стоимости фанов и очков чёрных цветов. Базовая выплата MCR остаётся равной 8. Конг цветов не получает бонуса за отсутствие джокеров.",
    "黑花递增计分：开启时梅兰竹菊1、2、3、4朵合计4、8、16、32番；关闭时每朵1番。花分不计入起和门槛。": "Прогрессивный счёт чёрных цветов: при включении 1, 2, 3 и 4 цветка сливы, орхидеи, бамбука и хризантемы дают в сумме 4, 8, 16 и 32 очка; при отключении каждый цветок даёт 1 очко. Цветы не учитываются в минимуме для победы.",
