    "对齐明星三缺一流程：见花见台、见风见台、每杠加一张尾牌、最多连 10、天地听不得过水、花胡可选。": "По порядку «明星三缺一»: тай за каждый цветок и ветер, каждый конг добавляет одну кость к хвосту, не более 10 повторных дилерств, при Небесной и Земной готовности нельзя пропускать победу; победа цветами настраивается.",
