    "单日峰值  ": "Максимум за день  ",
    "暂无日汇总": "Ежедневной сводки пока нет",
    " · 累计统计": " · Накопленная статистика",
    " · 近期公开牌谱": " · Последние публичные записи",
    "近期对局 · ": "Последние игры · ",
    " · 番种记录": " · Записи комбинаций",
    "日汇总截止 ": "Ежедневная сводка по ",
    "平台累计\n按当前规则及场次读取公开牌谱统计，对局按 game_id 去重。全场次含匹配、自定义和赛事；四张场次卡始终展示当前规则的累计数量。\n\n匹配场行为数据\n累计手数为全桌手数；平均和牌 = 总和牌番值 ÷ 和牌次数；自摸占和牌 = 自摸次数 ÷ 和牌次数。不展示个人胜率和个人顺位。\n\n每日对局量\n时间窗口只作用于日汇总，不改变累计指标与最近牌谱。统计日以北京时间 04:00 切日，截止最近已完成聚合日。缺少记录的日期留空，不补零。\n\n场次与局制\n初级、中级、高级、自定义的累计计数来自网站首页的原始牌谱归口接口。自定义部分缺少完整行为指标，只展示已提供的对局计数。\n\n最近对局\n全场次时展示匹配场公共牌谱，可按等级场筛选、翻页并查看同桌结算。赛事单独查询；现有接口未提供自定义房间公共牌谱列表。\n\n番种记录\n累计出现次数可重复，不是互斥占比。所选场次无支持时显示不可用。": "Итоги платформы\nСтатистика публичных записей по текущим правилам и категории; игры учитываются однократно по game_id. Все категории включают подбор, свои комнаты и турниры. Четыре карточки категорий всегда показывают накопленное число игр по текущим правилам.\n\nПоказатели игр с подбором\nЧисло рук учитывает весь стол; средняя стоимость победы = сумма фанов побед ÷ число побед; доля побед со стены = число побед со стены ÷ число побед. Личная доля побед и личные места не отображаются.\n\nЧисло игр по дням\nПериод действует только на ежедневную сводку и не меняет накопленные показатели и последние записи. Статистический день начинается в 04:00 по пекинскому времени; данные приведены по последнему полностью обработанному дню. Даты без записей остаются пустыми, а не заполняются нулями.\n\nКатегории и формат игр\nНакопленные числа игр начальной, средней, высшей категории и своих комнат получаются из исходного интерфейса группировки записей главной страницы сайта. Для части своих комнат нет полных показателей действий; отображается только доступное число игр.\n\nПоследние игры\nПри выборе всех категорий показываются публичные записи игр с подбором. Можно фильтровать по уровню комнаты, переходить по страницам и смотреть расчёт всего стола. Турниры запрашиваются отдельно; текущий интерфейс не предоставляет список публичных записей своих комнат.\n\nЗаписи комбинаций\nНакопленное число появлений допускает повторный учёт и не является долями взаимоисключающих категорий. Если выбранная категория не поддерживается, отображается недоступность.",
    "符": "фу",
    "台": "таи",
    "点": "очки",
    " 局": " сдач",
    "已解析 ": "Обработано ",
    " 场": " игр",
    "本规则暂未提供逐局统计": "Для этих правил статистика по сдачам пока недоступна",
    "统计范围\n所选规则、房间类型与日期同时作用于战绩和对局列表。\n\n和牌率 / 放铳率\n个人和牌次数 / 放铳次数 ÷ 参与的手数。\n\n自摸占和牌\n自摸次数 ÷ 和牌次数；不是每手自摸率。\n\n副露率\n个人副露手数 ÷ 参与的手数。\n\n平均顺位\n各顺位场次 × 顺位之和 ÷ 总场次。\n\n番种记录\n记录累计出现次数，可重复计数，不是互斥占比。\n\n近期走势\n最近最多 20 场，按时间从旧到新。缺少明细的指标显示“—”。": "Область статистики\nВыбранные правила, тип комнаты и даты действуют одновременно на результаты и список игр.\n\nДоля побед / набросов\nЛичное число побед / набросов ÷ число сыгранных рук.\n\nДоля побед со стены\nЧисло побед со стены ÷ число побед; это не доля побед со стены среди всех рук.\n\nДоля открытых рук\nЧисло личных рук с открытиями ÷ число сыгранных рук.\n\nСреднее место\nСумма произведений каждого места на число игр с этим местом ÷ общее число игр.\n\nЗаписи комбинаций\nУчитывается накопленное число появлений, возможен повторный учёт; это не доли взаимоисключающих категорий.\n\nПоследняя динамика\nНе более 20 последних игр, от старых к новым. Показатели без подробных данных отображаются как «—».",
