    "国标麻将：MCRPL场\n入场门槛：Salasasa七段及以上或职业五段及以上并实名注册\n场得pt：135\n场失pt：依照段位\n分配比例：+0.8+0.2-0.3-0.7\n对局设置：无提示 无指针提示 错和 战术鸣牌\n时间限制：20+5": "MCR: Комната MCRPL\nДопуск: 7 дан Salasasa или 5 профессиональный дан и выше, регистрация с настоящим именем\nПолучаемые pt: 135\nТеряемые pt: по рангу\nДоли распределения: +0.8+0.2-0.3-0.7\nНастройки: без подсказок и подсветки при наведении, ложная победа, тактические объявления\nВремя: 20+5",
