    "东、南、西、北分别组成四组刻子或杠子，另有一对将。": "По пангу или конгу Востока, Юга, Запада и Севера и ещё одна пара.",
    "中、发、白三组箭牌刻子或杠子，另有一组面子和将。": "Три панга или конга Красного, Зелёного и Белого драконов, ещё один сет и пара.",
    "仅使用 23468 条与发牌，例如 234678 条刻顺组合。": "Только 23468 бамбуков и Зелёный дракон, например сочетание пангов и чоу из 234678 бамбуков.",
    "同一门 1112345678999 加该门任一张牌。": "1112345678999 одной масти и любая ещё одна кость этой масти.",
    "四组杠子，剩余一对将牌组成和牌。": "Четыре конга и оставшаяся пара образуют выигрышную руку.",
    "同一门连续七个对子，例如 11223344556677 万。": "Семь последовательных пар одной масти, например 11223344556677 символов.",
    "一、九万饼条与东南西北中发白各一张，再成一对。": "По одной единице и девятке символов, точек и бамбуков, каждому ветру и дракону, с образованием одной пары.",
    "只由万、饼、条的一九牌组成刻子、杠子和将牌。": "Панги, конги и пара только из единиц и девяток символов, точек и бамбуков.",
    "东南西北中三组刻子或杠子，第四组为对子。": "Три панга или конга из Востока, Юга, Запада и Севера; четвёртый ветер — пара.",
    "中、发、白中两组刻子，一组对子，另有两组面子。": "Два панга и пара из Красного, Зелёного и Белого драконов, ещё два сета.",
    "手牌全部由东南西北中发白组成。": "Вся рука состоит из Востока, Юга, Запада, Севера, Красного, Зелёного и Белого драконов.",
    "四组暗刻或暗杠，另有一对将牌。": "Четыре закрытых панга или конга и ещё одна пара.",
    "一门 112233、556677、99 的七对结构。": "Структура семи пар одной масти: 112233, 556677 и 99.",
    "同一门四组完全相同的顺子，例如四组 123 万。": "Четыре полностью одинаковых чоу одной масти, например четыре чоу 123 символов.",
    "同一门四组连续递增的刻子，例如 111、222、333、444。": "Четыре панга одной масти с последовательно возрастающими номиналами, например 111, 222, 333, 444.",
    "同一门四组连续递进的顺子。": "Четыре последовательно смещённых чоу одной масти.",
    "三组杠子，另有一组面子和将牌。": "Три конга, ещё один сет и пара.",
    "万、饼、条的一九刻子与字牌刻子混合组成全副牌。": "Вся рука состоит из пангов единиц и девяток символов, точек и бамбуков вместе с пангами благородных.",
    "七个不同对子，例如 11223344556677。": "Семь разных пар, например 11223344556677.",
    "七张字牌齐全，另有三门各三张不相连序数牌。": "Все семь благородных костей и по три несвязанные числовые кости каждой из трёх мастей.",
    "全部由 2、4、6、8 序数牌组成的刻子和将牌。": "Панги и пара только из числовых костей 2, 4, 6 и 8.",
