    "同一门三组完全相同的顺子。": "Три полностью одинаковых чоу одной масти.",
    "同一门三组连续递增的刻子。": "Три панга одной масти с последовательно возрастающими номиналами.",
    "所有序数牌均为 7、8、9。": "Все числовые кости — 7, 8 и 9.",
    "所有序数牌均为 4、5、6。": "Все числовые кости — 4, 5 и 6.",
