    "同一门 123、456、789 三组顺子。": "Три чоу 123, 456 и 789 одной масти.",
    "三门各有 112233、556677、99 的双龙七对结构。": "Структура семи пар двух драконов: 112233, 556677 и 99 в трёх мастях.",
    "同一门三组按相同步长递进的顺子。": "Три чоу одной масти с одинаковым шагом смещения.",
    "每组面子和将牌都含有 5，例如 123、456、789。": "Каждый сет и пара содержат 5, например 123, 456, 789.",
    "三门各有同一序数的刻子，例如 555 万、555 饼、555 条。": "В каждой из трёх мастей панг одного номинала, например 555 символов, 555 точек и 555 бамбуков.",
    "三组暗刻或暗杠，另有一组面子和将牌。": "Три закрытых панга или конга, ещё один сет и пара.",
    "三门序数牌互不相连，且不含重复，配字牌组成特殊牌型。": "Неповторяющиеся несвязанные числовые кости трёх мастей вместе с благородными образуют особую форму руки.",
    "三门各取 147、258、369 之一组成组合龙。": "В каждой из трёх мастей выбирается одна из групп 147, 258 и 369, образуя Переплетённый ряд.",
    "全部序数牌均为 6、7、8、9。": "Все числовые кости — 6, 7, 8 и 9.",
    "全部序数牌均为 1、2、3、4。": "Все числовые кости — 1, 2, 3 и 4.",
    "东南西北中任取三组风牌刻子或杠子。": "Любые три панга или конга ветров из Востока, Юга, Запада и Севера.",
    "三门各有一组相连的顺子，合起来形成 123、456、789。": "По одному чоу каждой масти вместе образуют ряд 123, 456, 789.",
    "只使用牌面旋转后仍有对应关系的牌，如 123689 饼及白板。": "Только кости, сохраняющие соответствие при повороте, например 123689 точек и Белый дракон.",
    "三门各有同一数字的顺子，例如 123 万、123 饼、123 条。": "В каждой из трёх мастей чоу с одинаковыми числами, например 123 символов, 123 точек и 123 бамбуков.",
    "三门各有同一数字的刻子，例如 555 万、555 饼、555 条。": "В каждой из трёх мастей панг с одинаковым числом, например 555 символов, 555 точек и 555 бамбуков.",
    "满足和牌条件但全部番种被规则排除，计作无番和。": "Условия победы выполнены, но все комбинации исключены правилами; засчитывается Цыплячья рука.",
    "在牌山最后一张自摸和牌。": "Победа со стены последней костью.",
