    "other/rule/inclued_rule/新编MCR.pdf": "other/rule/inclued_rule/新编MCR.pdf",
    "在 Salasasa 免费在线玩国标麻将 MCR，支持自动算番、段位匹配和牌谱复盘。浏览器 2D 无需下载，另有多规则客户端与麻将学习工具。": "Играйте бесплатно в MCR на Salasasa: автоматический подсчёт очков, подбор по рангу и просмотр записей игр. Версия 2D работает в браузере без скачивания; также доступны клиент с разными правилами и инструменты изучения маджонга.",
    "免费在线玩国标麻将 MCR | Salasasa": "Бесплатный маджонг MCR онлайн | Salasasa",
    "在浏览器中免费进行国标麻将 MCR 对局，支持自动算番、段位匹配与牌谱复盘，界面提供简繁中文、英语、日语和法语。": "Играйте бесплатно в MCR в браузере с автоматическим подсчётом очков, подбором по рангу и просмотром записей. Интерфейс доступен на упрощённом и традиционном китайском, английском, японском и французском.",
    "东南西北": "Восток, Юг, Запад, Север",
