    "剩余张数提示": "Подсказка оставшихся костей",
    "136张无花牌，0翻可和；吃碰明杠后仅可自摸，打出混儿后本局不可和牌。庄家和牌连庄，其余轮庄。": "136 костей без цветов, победа разрешена с 0 удвоений. После чоу, панга или открытого конга можно победить только со стены; после сноса джокера победа в этой сдаче запрещена. При победе дилер сохраняется, иначе меняется.",
    "可选规则变体（默认关闭）": "Дополнительные варианты правил (по умолчанию отключены)",
    "每张不按本体使用的混儿减1翻，最低保留1翻；原本0翻的和牌仍按0翻结算。": "Каждый джокер, использованный не как исходная кость, уменьшает число удвоений на 1, но оставляет не менее 1. Рука, исходно имевшая 0 удвоений, рассчитывается с 0.",
    "阅读北京麻将（吃碰提）完整规则与变体说明": "Прочитать полные правила пекинского маджонга (чоу, панг и ти) и описание вариантов",
    "长春 ·": "Чанчунь · ",
    "末张单放：": "Отдельный снос последней кости: ",
    "应付": "К выплате",
    "，由座位": ", платит место ",
    "包庄": "Ответственность дилера",
    "MIL 2024：136张、十三张手牌，三门带幺九，可吃碰杠和报听。一条仅可在特殊杠中代牌；报听后看宝，六番封顶。三张特殊杠首次不补牌，以后每加一张补一张。": "MIL 2024: 136 костей, рука из тринадцати костей, три масти и терминальные обязательны. Разрешены чоу, панг, конг и объявление готовности. Единица бамбуков заменяет кости только в особом конге; после объявления готовности можно смотреть сокровище. Предел — шесть фанов. За первоначальный особый конг из трёх костей замены нет; затем каждая добавленная кость заменяется одной.",
    "有效申请后可在5秒内以更高优先级抢断；机器人入座自动关闭": "В течение 5 секунд после действительной заявки её можно перехватить действием с более высоким приоритетом; автоматически отключается при появлении бота",
