    "{count}分封顶（含鸟）": "Предел очков: {count} (с птицами)",
    "开杠后按骰子位置公开补牌；卡摸仅限制小胡点和。封顶按每名和牌者、每名付款者计算，同批多次和牌累计计入封顶。": "После конга замещающие кости открываются в позиции, определённой кубиками. Ограничение малой победы запрещает только малую победу со сноса. Предел применяется отдельно к каждому победителю и каждому плательщику; несколько побед в одном пакете суммируются для проверки предела.",
    "开局有2秒可选择全桌不换；换完一轮后可选择再换一轮，最多两轮。每轮选六张、最多两种花色；三种花色失去和牌资格。固定四张开杠、双鸟、小胡2分、大胡8分起、不封顶。": "В начале есть 2 секунды, чтобы выбрать отказ всего стола от обмена. После первого обмена можно выбрать ещё один, максимум два раунда. В каждом выбираются шесть костей не более чем двух мастей; три масти лишают права на победу. Фиксированы четыре кости после конга, две птицы, малая победа 2 очка, большая от 8 очков, без предела.",
    "经典双鸟": "Классические две птицы",
    "换牌时间（秒）": "Время обмена (с)",
    "社群二维码": "QR-код сообщества",
    "裁切标题图片": "Обрезать изображение заголовка",
    "拖动图片调整位置，滚轮或滑块缩放。裁切比例与侧栏封面一致（约 2.2:1）。": "Перетаскивайте изображение для перемещения, используйте колесо или ползунок для масштаба. Пропорции обрезки совпадают с обложкой боковой панели (около 2.2:1).",
    "缩放": "Масштаб",
