    "起始与返点均为40000点，顺位点为0；每副144张，包含8张不同赖子。两副牌组交替使用。": "Начальный и возвратный счёт — 40000 очков, очки за место — 0. В каждом наборе 144 кости, включая 8 разных джокеров. Два набора используются поочерёдно.",
    "阅读夺彩麻将规则书与赖子图鉴": "Прочитать правила маджонга Доцай и справочник джокеров",
    "清空全部": "Очистить всё",
    "四家均预置 13 张手牌、8 张固定牌墙，另设 24 张公共牌墙。庄家开牌首摸取自固定墙；一家摸空后，剩余固定牌按东南西北接到公共墙前。": "Каждому заранее задаются 13 костей руки и 8 костей фиксированной стены; отдельно задаётся общая стена из 24 костей. Первую кость дилер берёт из фиксированной стены. Когда один игрок исчерпает её, оставшиеся фиксированные кости добавляются перед общей стеной в порядке Восток, Юг, Запад, Север.",
    "四家均预置 13 张手牌、14 张个人牌墙。庄家开牌首摸取自个人牌墙。无公共牌墙，不预先把庄家第一张摸牌放入手牌。": "Каждому заранее задаются 13 костей руки и 14 костей личной стены. Первую кость дилер берёт из личной стены. Общей стены нет; первая кость дилера заранее в руку не добавляется.",
    "副：": "Сдача: ",
    "家坐庄。牌墙从第 1 张开始依次摸取。": " — дилер. Кости стены берутся по порядку, начиная с 1-й.",
