    "起和点数": "Минимум очков для победы",
    "只允许碰彩虹，不允许普通碰牌。每位玩家每局最多补牌两次。无色牌可组成对子或同色顺子，不能组成刻子或彩虹。": "Разрешён только радужный панг, обычные панги запрещены. Каждый игрок может добрать кости не более двух раз за сдачу. Бесцветные кости образуют пары или одноцветные чоу, но не панги и не радуги.",
    "阅读完整规则书": "Прочитать полные правила",
