    "和牌张按": "Выигрышная кость считается как ",
    "MIL 2024：112张、十三张手牌，红中为万能牌，仅可自摸；可碰杠，不吃。最高四番，和牌后扎两鸟，流局退杠。": "MIL 2024: 112 костей, рука из тринадцати костей, Красный дракон — универсальный джокер; победа только со стены. Панги и конги разрешены, чоу запрещено. Предел — четыре фана; после победы выбираются две птицы, при ничьей выплаты за конги возвращаются.",
    "阅读 MIL 红中规则书": "Прочитать правила Красного дракона MIL",
    "九江麻将是九江地区一个没落的麻将规则，目前九江地区通行红中麻将，本规则是芋蔗凭借小时候的记忆和一定程度上的改良复现的一种失传规则，如发现任何问题或者能够提供九江麻将的资料的玩家可以联系Q2264033554": "Маджонг Цзюцзяна — вышедшие из употребления местные правила; сейчас в регионе распространён маджонг Красного дракона. Юйчжэ восстановил эти утраченные правила по детским воспоминаниям с некоторыми улучшениями. Если вы нашли проблему или располагаете материалами о маджонге Цзюцзяна, свяжитесь через QQ 2264033554.",
    "下载九江麻将规则书": "Скачать правила маджонга Цзюцзяна",
