    "传统84张，东南西三席，5番起和。飞可作百搭或当花；花套与杠即时结算，和牌后另比输家花分与三家飞牌。": "Традиционные 84 кости, три места: Восток, Юг и Запад; минимум пять фанов. Фэй используется как джокер или цветок. Наборы цветов и конги оплачиваются сразу; после победы отдельно сравниваются очки цветов проигравших и кости фэй всех троих.",
