    "山西麻将 · MIL试行2023版。136张、十三张手牌、无花无癞子；须暗扣报听，有和必和，和牌时结杠。": "Маджонг Шаньси · Пробная версия MIL 2023. 136 костей, рука из тринадцати, без цветов и джокеров. Готовность объявляется закрытым сносом, доступную победу пропускать нельзя; конги рассчитываются при победе.",
    "局时是每局额外思考储备，默认20秒；每次操作先使用步时，默认5秒。零局时只使用步时。": "Время на сдачу — дополнительный запас обдумывания, по умолчанию 20 секунд. Каждое действие сначала использует время на ход, по умолчанию 5 секунд. При нулевом запасе действует только время на ход.",
