    "资料修改申请待审核": "Заявка на изменение сведений ожидает проверки",
    "下方为已提交的内容，如需继续修改，请先撤销申请。": "Ниже показано отправленное содержимое. Чтобы продолжить изменения, сначала отзовите заявку.",
