    "跟随已有密钥": "По существующему ключу",
    "支持本赛事／基地的手动牌山、复现牌山、密钥牌山；规则须与房间一致。": "Поддерживаются ручная, воспроизведённая и заданная ключом стены этого турнира или клуба; правила должны совпадать с комнатой.",
    "自动生成复式密钥": "Автоматически создать ключ дубликата",
    "每个房间生成并绑定一个独立密钥，本次创建": "Для каждой комнаты создаётся и привязывается отдельный ключ. Сейчас будет создано ",
    "个密钥。花牌使用上方设置，局数跟随密钥。": " ключей. Цветы определяются настройками выше, число сдач — ключом.",
    "今日已创建": "Сегодня создано ",
    "个，剩余": ", осталось ",
    "个；可保存": "; можно хранить ",
    "个。额度由场馆管理员共用，北京时间零点刷新。": ". Лимит общий для администраторов площадки и обновляется в полночь по пекинскому времени.",
    "阅读温州 MIL 2024 规则书": "Прочитать правила Вэньчжоу MIL 2024",
    "MIL 2025：136张，皮癞单张杠；必须开口，逐家六番起和。末四张只能自摸或过，七皮、十杠途中结算，轮庄。鸣牌响应为3秒。": "MIL 2025: 136 костей, указатель и джокер объявляются конгом по одной кости. Требуется открытая рука, минимум шесть фанов проверяется против каждого игрока. На последних четырёх костях доступны только победа со стены или пропуск; семь указателей и десять конгов вызывают досрочный расчёт; дилер меняется. Ответ на объявление — 3 секунды.",
    "阅读 MIL 武汉规则书": "Прочитать правила Уханя MIL",
    "144张、十三张手牌；可吃碰杠，逐张补花。2花自摸、3花放冲、1花独吊；固定牌型已含胡牌底花。": "144 кости, рука из тринадцати; разрешены чоу, панг и конг, цветы заменяются по одному. Победа со стены — от 2 цветов, со сноса — от 3, с единственным ожиданием — от 1; фиксированные комбинации уже включают базовые цветы за победу.",
    "阅读宜兴规则书": "Прочитать правила Исина",
    "OMU管理后台": "Панель управления OMU",
    "返回账户面板": "Вернуться в личный кабинет",
    "其他数据": "Другие данные",
    "复式使用说明": "Руководство по дубликату",
