    "暂无可管理的赛事或基地。申办完成或成为管理员后可创建。": "Нет доступных для управления турниров или клубов. Создание будет доступно после одобрения заявки или назначения администратором.",
    "今日创建": "Создано сегодня",
    "保留密钥": "Сохранённые ключи",
