    "例如：第一轮 · A 组": "Например: первый тур · Группа A",
    "川麻牌山布局": "Расположение стены Сычуани",
    "庄家也只预置 13 张，开牌时再从自己的牌墙头摸一张。东南西北方位固定，庄家依次轮转。": "Дилеру также заранее задаются только 13 костей; при начале игры он берёт ещё одну с начала своей стены. Направления Восток, Юг, Запад и Север фиксированы, дилерство передаётся по очереди.",
    "牌山类型": "Тип стены",
    "1–128 个字符的文本种子": "Текстовое начальное значение длиной 1–128 символов",
    "一个种子生成整场牌山。相同规则、花牌设置、局数和种子生成相同的手牌与牌山。": "Одно начальное значение создаёт стены для всей игры. Одинаковые правила, настройка цветов, число сдач и начальное значение дают одинаковые руки и стены.",
    "编辑各局牌山": "Изменить стены отдельных сдач",
    "密钥默认锁定，解除锁定后公开牌谱。": "По умолчанию ключ заблокирован; после разблокировки записи становятся публичными.",
