    "仅自摸；蓝色牌为杠补自动弃牌，不能吃碰杠。宝牌杠弃不计飞宝。": "Победа только со стены; синие кости — автоматические сносы замены после конга, на них нельзя объявлять чоу, панг или конг. Снос бонусной кости после конга не считается Летящим сокровищем.",
    "本副净分：": "Чистый счёт сдачи: ",
