    "我": "Я",
    "初始 R 为 1500，仅系统匹配计分，自建房不计。": "Начальный R — 1500. Учитываются только игры с системным подбором, свои комнаты не учитываются.",
    "预期胜率 = 1 / (1 + 10^((对手 R − 自己 R) / 2000))。": "Ожидаемая вероятность победы = 1 / (1 + 10^((R соперника − свой R) / 2000)).",
    "变化值 = 32 ×（实际结果 − 预期胜率），结果四舍五入为整数；胜为 1，负为 0。": "Изменение = 32 × (фактический результат − ожидаемая вероятность победы), с округлением до целого; победа — 1, поражение — 0.",
    "历史积分按迁移前原分 + 500 修正，之后已结算的积分变化、胜负和场数保留。": "Исторический рейтинг скорректирован как прежний рейтинг + 500; последующие рассчитанные изменения, победы, поражения и число игр сохранены.",
