    "再来一局": "Ещё раз",
    "点击下方牌面添加手牌；点击副露框后，只有能组成合法牌组的牌会高亮可点。 手牌 + 副露合计最多 14 张，所有牌必须分成 3 张及以上的合法牌组，无雀头。 自摸支持连续加杠预测；手牌为空时也可输入副露，查看可摸入的和牌张。": "Нажимайте на кости внизу, чтобы добавить их в руку. После выбора ячейки объявленного сета доступны только кости, образующие допустимую группу. Рука и объявленные группы вместе — не более 14 костей; все кости должны образовать допустимые группы по 3 или более, без пары. Для победы со стены прогнозируются последовательные дополненные конги. Даже при пустой руке можно ввести объявленные группы и посмотреть выигрышные взятия.",
    "输入手牌或副露后计算和牌与预测": "Введите руку или объявленные группы для расчёта победы и прогноза",
    "加杠顺序": "Порядок дополнения конгов",
