    "当前牌型未成和牌；可查看下方摸入一张后的预测。": "Текущая рука не выигрышная; ниже можно посмотреть прогноз после взятия одной кости.",
    "摸牌后的和牌预测（": "Прогноз победы после взятия (",
    "种）": " видов)",
    "“仅自摸”需摸入后按顺序加杠；其他玩家的弃牌不能用于这种和法。展开查看加杠步骤与最终牌型。": "«Только со стены» требует после взятия дополнить конги в указанном порядке; снос другого игрока для такой победы не подходит. Разверните, чтобы посмотреть шаги дополнения и итоговую руку.",
    "仅自摸 ·": "Только со стены · ",
