    "；和牌": "; победа ",
    "12/13 张显示向听与进张效率，14 张显示切牌效率。 已和牌仍会列出可继续扩展的进张；一向听、两向听、三向听及以上都会计算能减少向听的进张。 每种牌只有一张。输入为空时随机生成 14 张。计算在浏览器本地完成。": "При 12/13 костях показываются шантен и эффективность улучшений, при 14 — эффективность сноса. Для уже выигрышной руки также перечисляются кости, позволяющие её расширять. Для одного, двух, трёх и более шантен рассчитываются взятия, уменьшающие шантен. Каждая кость существует в одном экземпляре. При пустом вводе случайно создаются 14 костей. Расчёт выполняется локально в браузере.",
